INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Datenquellen immer Datenbanken?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dateien, Sensoren möglich"}, {"text": "Ja", "correct": false, "because": "Verschiedene Typen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Nutzung von Datenquellen?', 3, '[{"text": "Daten bereitstellen", "correct": true, "because": "Grundlage für Verarbeitung"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk sichern", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Datenquellen gibt es?', 5, '[{"text": "Datenbanken", "correct": true, "because": "Strukturierte Daten"}, {"text": "API", "correct": true, "because": "Dynamische Daten"}, {"text": "Monitorgröße", "correct": false, "because": "Kein Datenlieferant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenquellen liefern Rohdaten. b) Sie sind immer lokal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch remote möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Datenquellen?', 4, '[{"text": "Datenformat", "correct": false, "because": "Bestimmt Verarbeitung"}, {"text": "Zuverlässigkeit", "correct": false, "because": "Sichert Qualität"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenquellen immer digital sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch analoge Quellen möglich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenquelle liefert Echtzeitdaten?', 3, '[{"text": "Sensoren", "correct": true, "because": "Erfassen live"}, {"text": "Textdatei", "correct": false, "because": "Statisch"}, {"text": "Excel", "correct": false, "because": "Statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Datenquellen?', 5, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Qualität der Daten"}, {"text": "Verfügbarkeit", "correct": true, "because": "Zugriff möglich"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenquellen können extern sein. b) Sie sind immer kostenlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Datenquelle?', 4, '[{"text": "Datenformat", "correct": false, "because": "Verarbeitung nötig"}, {"text": "Zugriffsmethode", "correct": false, "because": "Erforderlich"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Datenquellen immer statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Dynamische Quellen möglich"}, {"text": "Ja", "correct": false, "because": "Variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenquellen sind für Big Data typisch?', 4, '[{"text": "Social Media", "correct": true, "because": "Große Datenmengen"}, {"text": "IoT-Geräte", "correct": true, "because": "Echtzeitdaten"}, {"text": "Papierdokumente", "correct": false, "because": "Nicht digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Datenquellen immer sicher sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit muss gewährleistet werden"}, {"text": "Ja", "correct": false, "because": "Risiken existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Datenquellen?', 3, '[{"text": "Qualität", "correct": true, "because": "Verlässlichkeit entscheidend"}, {"text": "Schnelle Verfügbarkeit", "correct": false, "because": "Qualität wichtiger"}, {"text": "Minimale Kosten", "correct": false, "because": "Zuverlässigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenquellen können APIs sein. b) Sie sind immer intern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch extern möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei Datenquellen?', 5, '[{"text": "Heterogenität", "correct": true, "because": "Verschiedene Formate"}, {"text": "Zuverlässigkeit", "correct": true, "because": "Datenqualität"}, {"text": "Monitorauflösung", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Datenquellen unwichtig?', 3, '[{"text": "Datenformat", "correct": false, "because": "Bestimmt Verarbeitung"}, {"text": "Zugriffskontrolle", "correct": false, "because": "Schützt Daten"}, {"text": "Tastaturdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Liefern Datenquellen immer Echtzeitdaten?', 3, '[{"text": "Nein", "correct": true, "because": "Auch statische Daten"}, {"text": "Ja", "correct": false, "because": "Abhängig von Quelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenquellen nur digital sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch analoge Quellen"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Zuverlässigkeit?', 4, '[{"text": "Sichert Datenqualität", "correct": true, "because": "Verlässliche Ergebnisse"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Kein Netzwerkeffekt"}, {"text": "Verbessert Grafik", "correct": false, "because": "Irrelevant"}]');
